n=22
grid=[[4]*n for _ in range(n)]
objs=[(1,0,8,2),(0,17,2,9),(5,5,8,3),(8,12,2,6),(12,17,2,7),(14,0,8,9)]
for r,c,border,core in objs:
    for i in range(5):
        for j in range(5):
            grid[r+i][c+j]= core if 1<=i<=3 and 1<=j<=3 else border
print('\n'.join(' '.join(map(str,row)) for row in grid))
